329	/// Collect triggered abilities from events and add them to the stack
330	/// in APNAP order (active player first on bottom, non-active player on top).
331	///
332	/// Does NOT resolve them — the game loop resolves them one at a time,
333	/// giving players priority between each.
334	pub fn collect_triggers(state: &mut GameState, registry: &CardRegistry) {
335	    let events = state.events.clone();
336	    let start = state.trigger_event_index;
337	    let active_player = state.active_player;
338	
339	    let mut ap_triggers: Vec<PendingTrigger> = Vec::new();
340	    let mut nap_triggers: Vec<PendingTrigger> = Vec::new();
341	
342	    for (i, event) in events.iter().enumerate().skip(start) {
343	        match event {
344	            GameEvent::EnteredBattlefield { object, .. } => {
345	                let (card_id, controller) = match state.get_object(*object) {
346	                    Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
347	                    _ => continue,
348	                };
349	                // Only collect if the card has an on_enter_battlefield handler.
350	                // Self ETB trigger.
351	                if registry.get(card_id).is_some() {
352	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::EntersBattlefield, false);
353	                    let trigger = PendingTrigger::EnteredBattlefield {
354	                        object_id: *object,
355	                        card_id,
356	                        controller,
357	                        description: desc,
358	                    };
359	                    if controller == active_player {
360	                        ap_triggers.push(trigger);
361	                    } else {
362	                        nap_triggers.push(trigger);
363	                    }
364	                }
365	
366	                // ETB-watch: notify other permanents that a creature entered.
367	                if state.get_object(*object).map(|o| o.power.is_some()).unwrap_or(false) {
368	                    let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
369	                        .filter(|o| o.zone == Zone::Battlefield && o.id != *object)
370	                        .map(|o| (o.id, o.card_id, o.controller))
371	                        .collect();
372	                    for (watcher_id, watcher_card_id, watcher_controller) in watchers {
373	                        if registry.get(watcher_card_id).is_some() {
374	                            let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureEnters, false);
375	                            if !desc.is_empty() {
376	                                let trigger = PendingTrigger::EnterWatch {
377	                                    watcher_id,
378	                                    watcher_card_id,
379	                                    controller: watcher_controller,
380	                                    entered_id: *object,
381	                                    entered_controller: controller,
382	                                    description: desc,
383	                                };
384	                                if watcher_controller == active_player {
385	                                    ap_triggers.push(trigger);
386	                                } else {
387	                                    nap_triggers.push(trigger);
388	                                }
389	                            }
390	                        }
391	                    }
392	                }
393	            }
394	            GameEvent::CreatureDied { object, card_id, controller, damaged_by, last_known_toughness } => {
395	                let dead_id = *object;
396	                let dead_card_id = *card_id;
397	                let dead_controller = *controller;
398	                let dead_damaged_by = damaged_by.clone();
399	                let dead_toughness = *last_known_toughness;
400	
401	                // 1. Self-dies trigger.
402	                if registry.get(dead_card_id).is_some() {
403	                    let desc = trigger_description(registry, dead_card_id, &crate::cards::TriggerKind::SelfDies, false);
404	                    let trigger = PendingTrigger::SelfDies {
405	                        dead_id,
406	                        dead_card_id,
407	                        controller: dead_controller,
408	                        description: desc,
409	                    };
410	                    if dead_controller == active_player {
411	                        ap_triggers.push(trigger);
412	                    } else {
413	                        nap_triggers.push(trigger);
414	                    }
415	                }
416	
417	                // 2. Death-watch: collect triggers from all permanents on battlefield.
418	                let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
419	                    .filter(|o| o.zone == Zone::Battlefield && o.id != dead_id)
420	                    .map(|o| (o.id, o.card_id, o.controller))
421	                    .collect();
422	                for (watcher_id, watcher_card_id, watcher_controller) in watchers {
423	                    if registry.get(watcher_card_id).is_some() {
424	                        let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureDies, false);
425	                        let trigger = PendingTrigger::DeathWatch {
426	                            watcher_id,
427	                            watcher_card_id,
428	                            controller: watcher_controller,
429	                            dead_id,
430	                            dead_controller,
431	                            dead_damaged_by: dead_damaged_by.clone(),
432	                            dead_toughness,
433	                            description: desc,
434	                        };
435	                        if watcher_controller == active_player {
436	                            ap_triggers.push(trigger);
437	                        } else {
438	                            nap_triggers.push(trigger);
439	                        }
440	                    }
441	                }
442	            }
443	            GameEvent::LeftBattlefield { object, .. } => {
444	                let (card_id,) = match state.get_object(*object) {
445	                    Some(o) => (o.card_id,),
446	                    None => continue,
447	                };
448	                if registry.get(card_id).is_some() {
449	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::LeavesBattlefield, false);
450	                    let trigger = PendingTrigger::LeftBattlefield {
451	                        object_id: *object,
452	                        card_id,
453	                        description: desc,
454	                    };
455	                    // LTB triggers go on AP side (they're usually self-referential).
456	                    ap_triggers.push(trigger);
457	                }
458	            }
459	            GameEvent::CombatDamageDealt { source, target, amount } => {
460	                // Creature-to-creature combat damage triggers.
461	                if let crate::events::DamageTarget::Object(damaged_id) = target {
462	                    let source_id = *source;
463	                    if let Some(obj) = state.get_object(source_id) {
464	                        if obj.zone == Zone::Battlefield && obj.power.is_some() {
465	                            let card_id = obj.card_id;
466	                            let controller = obj.controller;
467	                            if registry.get(card_id).is_some() {
468	                                let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::DealsCombatDamageToCreature, false);
469	                                if !desc.is_empty() {
470	                                    let trigger = PendingTrigger::CombatDamageToCreature {
471	                                        creature_id: source_id,
472	                                        creature_card_id: card_id,
473	                                        controller,
474	                                        damaged_creature: *damaged_id,
475	                                        amount: *amount,
476	                                        description: desc,
477	                                    };
478	                                    if controller == active_player {
479	                                        ap_triggers.push(trigger);
480	                                    } else {
481	                                        nap_triggers.push(trigger);
482	                                    }
483	                                }
484	                            }
485	                        }
486	                    }
487	                }
488	                // Creature-to-player combat damage triggers.
489	                if let crate::events::DamageTarget::Player(damaged_player) = target {
490	                    let source_id = *source;
